package wsrv_test

import (
	"encoding/json"
	"net/url"
	"os"
	"path/filepath"
	"testing"

	"github.com/xantiagoma/xtandard-image/internal/dialect"
)

// unpicEntry is one URL generated by unpic's wsrv provider
// (testdata/unpic/generate.ts).
type unpicEntry struct {
	Name   string `json:"name"`
	URL    string `json:"url"`
	Source string `json:"source"` // what unpic's extract() reads back
}

func loadUnpic(tb testing.TB) []unpicEntry {
	tb.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "unpic", "corpus.json"))
	if err != nil {
		tb.Fatal(err)
	}
	var corpus []unpicEntry
	if err := json.Unmarshal(b, &corpus); err != nil {
		tb.Fatal(err)
	}
	return corpus
}

// TestUnpicCorpus parses the URLs unpic generates for wsrv (its test cases
// plus every documented operation); the expected requests are in
// golden/unpic.json, and the source must equal unpic's own extract().
func TestUnpicCorpus(t *testing.T) {
	t.Parallel()
	corpus := loadUnpic(t)
	if len(corpus) < 30 {
		t.Fatalf("corpus has %d entries, want >= 30", len(corpus))
	}
	cases := make([]testCase, 0, len(corpus))
	for _, e := range corpus {
		u, err := url.Parse(e.URL)
		if err != nil {
			t.Fatal(err)
		}
		cases = append(cases, testCase{name: e.Name, path: u.EscapedPath(), query: u.RawQuery})
	}
	runGolden(t, "unpic", cases)

	p := getFixture(t).parsers["default"]
	for i, e := range corpus {
		res, err := p.Parse(&dialect.Input{Path: cases[i].path, RawQuery: cases[i].query})
		if err != nil {
			t.Errorf("%s: %v", e.Name, err)
			continue
		}
		if res.SourceString != e.Source {
			t.Errorf("%s: source %q, want %q", e.Name, res.SourceString, e.Source)
		}
		for _, ig := range res.Request.Ignored {
			if ig.Reason == "unknown option" || ig.Reason == "not implemented" {
				t.Errorf("%s: %s: %s", e.Name, ig.Option, ig.Reason)
			}
		}
	}
}
